import{_ as o,o as e,c as t,ag as r}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"心理学与认知","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/psychology/index.md","filePath":"topics/psychology/index.md"}'),n={name:"topics/psychology/index.md"};function i(s,a,d,h,l,c){return e(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="心理学与认知" tabindex="-1">心理学与认知 <a class="header-anchor" href="#心理学与认知" aria-label="Permalink to &quot;心理学与认知&quot;">​</a></h1><blockquote><p>整理自各类视频、播客、书籍中的心理学洞察与认知方法</p></blockquote><hr><h2 id="核心议题" tabindex="-1">核心议题 <a class="header-anchor" href="#核心议题" aria-label="Permalink to &quot;核心议题&quot;">​</a></h2><h3 id="_1-精力管理" tabindex="-1">1. 精力管理 <a class="header-anchor" href="#_1-精力管理" aria-label="Permalink to &quot;1. 精力管理&quot;">​</a></h3><p><strong>核心：</strong> 大脑只运算不存储，后台进程消耗精力。</p><p>→ 详见：<code>energy-management.md</code></p><h3 id="_2-共情与安慰" tabindex="-1">2. 共情与安慰 <a class="header-anchor" href="#_2-共情与安慰" aria-label="Permalink to &quot;2. 共情与安慰&quot;">​</a></h3><p><strong>核心：</strong> 安慰不是给建议，是承认对方的感受真实存在。</p><p>→ 详见：<code>empathy-and-consolation.md</code></p><h3 id="_3-匪气-vs-书生气" tabindex="-1">3. 匪气 vs 书生气 <a class="header-anchor" href="#_3-匪气-vs-书生气" aria-label="Permalink to &quot;3. 匪气 vs 书生气&quot;">​</a></h3><p><strong>核心：</strong> 面子是可再生资源，开口三分利，被拒绝的成本接近于零。</p><p>→ 详见：<code>fei-qi-vs-shu-sheng-qi.md</code></p><h3 id="_4-镜映与自我评价" tabindex="-1">4. 镜映与自我评价 <a class="header-anchor" href="#_4-镜映与自我评价" aria-label="Permalink to &quot;4. 镜映与自我评价&quot;">​</a></h3><p><strong>核心：</strong> 自我评价常源于&quot;外界的镜子&quot;（照顾者/伴侣/前任/平台数据），渴望被看见。拆法 = 外面当参考不当裁判。</p><p>→ 详见：<code>mirroring-self-evaluation.md</code></p><h3 id="_5-从-数字-到-有名字的人" tabindex="-1">5. 从&quot;数字&quot;到&quot;有名字的人&quot; <a class="header-anchor" href="#_5-从-数字-到-有名字的人" aria-label="Permalink to &quot;5. 从&quot;数字&quot;到&quot;有名字的人&quot;&quot;">​</a></h3><p><strong>核心：</strong> 游戏士兵去数字化情感——名字+共同经历=杀不死的人；抽象无法共情，具名才触发。魁拔幽弥狂（官方不给的纹耀，魁拔给了）。</p><p>→ 详见：<code>game-soldier-rehumanization.md</code></p><h3 id="_6-德西效应与内在动机" tabindex="-1">6. 德西效应与内在动机 <a class="header-anchor" href="#_6-德西效应与内在动机" aria-label="Permalink to &quot;6. 德西效应与内在动机&quot;">​</a></h3><p><strong>核心：</strong> 外部奖励介入会削弱内在动机（过度理由效应）。奖励有顶、热爱无底——识别&quot;被过度理由化的领域&quot;，剥离外部信号，重连内在愉悦。与 Echo Gap 奖励膨胀正反同构。</p><p>→ 详见：<code>deci-effect-intrinsic-motivation.md</code></p><h3 id="_7-君子论迹不论心-课题分离少内耗" tabindex="-1">7. 君子论迹不论心：课题分离少内耗 <a class="header-anchor" href="#_7-君子论迹不论心-课题分离少内耗" aria-label="Permalink to &quot;7. 君子论迹不论心：课题分离少内耗&quot;">​</a></h3><p>（见 junzi-acts-not-intent.md —— 放下对他人动机的揣测，以客观行为与结果为纲；阿德勒课题分离、五个场景化操作）</p><h3 id="_8-提前焦虑-vs-提前规划-焦虑到底有没有用" tabindex="-1">8. 提前焦虑 vs 提前规划：焦虑到底有没有用 <a class="header-anchor" href="#_8-提前焦虑-vs-提前规划-焦虑到底有没有用" aria-label="Permalink to &quot;8. 提前焦虑 vs 提前规划：焦虑到底有没有用&quot;">​</a></h3><p><strong>核心：</strong> 焦虑出厂设置没错（它在报警），但它<strong>只会报警、不会灭火</strong>——唯一有用的那一刻，是你把它翻译成具体动作的那一刻。驱动行动的是计划不是焦虑；只焦虑不行动就落入&quot;贷款吃屎&quot;式预支痛苦。含<strong>耶克斯-多德森定律的两处打折</strong>：原始论文是小鼠&quot;刺激强度→习惯形成速度&quot;（1908），&quot;定律&quot;头衔是后来引用者封的（半世纪仅 10 次引用、4 次称 law；2015 年有论文题为《从定律到民俗》）。</p><p>→ 详见：<code>anxiety-planning.md</code></p><hr><h2 id="主题索引" tabindex="-1">主题索引 <a class="header-anchor" href="#主题索引" aria-label="Permalink to &quot;主题索引&quot;">​</a></h2>',29)])])}const q=o(n,[["render",i]]);export{u as __pageData,q as default};
